    const rate=calculateTrafficRate(previousTraffic.current,traffic);
    previousTraffic.current=traffic;
    if(rate){setData(current=>({...current,dashboard:{...current.dashboard,traffic:{...rate,ready:true},activeInterfaces:traffic.activeInterfaces}}));setTrafficHistory(current=>[...current.slice(-299),rate]);setTrafficStatus('live');setTrafficError('');}
