    if(!Number.isInteger(Number(voucherForm.nameLength))||Number(voucherForm.nameLength)<1||Number(voucherForm.nameLength)>16)return Alert.alert('Panjang nama tidak valid','Masukkan panjang nama antara 1 sampai 16 karakter.');
