        form:{...voucherForm,price:selected.price||storedMeta.price||voucherForm.price||'',sellingPrice:selected.sellingPrice||selected['selling-price']||storedMeta.sellingPrice||voucherForm.sellingPrice||voucherForm.price||'',validity:selected.validity||storedMeta.validity||voucherForm.validity||''},
