  const removeHotspotProfile=item=>Alert.alert('Hapus profil Hotspot?',`Profil ${item.name} akan dihapus dari MikroTik. User yang masih memakai profil ini mungkin terdampak.`,[{text:'Batal',style:'cancel'},{text:'Hapus',style:'destructive',onPress:async()=>{try{await api(`/api/hotspot/profiles/${encodeURIComponent(item['.id']||item.name)}`,{method:'DELETE'});const nextMeta={...hotspotProfileMeta};delete nextMeta[item.name];setHotspotProfileMeta(nextMeta);await AsyncStorage.setItem(HOTSPOT_PROFILE_META_KEY,JSON.stringify(nextMeta));setDetailItem(null);await loadData('hotspot',true);}catch(e){Alert.alert('Gagal menghapus profil',e.message||'Profil tidak dapat dihapus. Periksa apakah masih dipakai user.');}}}]);
  const removeVoucher=item=>Alert.alert('Hapus voucher?',`Voucher ${item.name} akan dihapus dari MikroTik.`,[{text:'Batal',style:'cancel'},{text:'Hapus',style:'destructive',onPress:async()=>{try{await api(`/api/hotspot/users/${encodeURIComponent(item['.id'])}`,{method:'DELETE'});await loadData('hotspot',true);}catch(e){Alert.alert('Gagal menghapus voucher',e.message);}}}]);
  const showVoucherActions=item=>{const active=data.hotspotActive.find(session=>session.user===item.name||session.name===item.name);setDetailItem({type:'voucher',item:{...item,uptime:active?.uptime||'',sessionActive:Boolean(active),...(item['mac-address']||active?.['mac-address']?{'mac-address':item['mac-address']||active?.['mac-address']}:{})}});};
  const toggleInterface=(item,enabled)=>Alert.alert(`${enabled?'Aktifkan':'Nonaktifkan'} interface?`,`Interface ${item.name||''} akan ${enabled?'diaktifkan':'dinonaktifkan'} pada router.`,[{text:'Batal',style:'cancel'},{text:enabled?'Aktifkan':'Nonaktifkan',style:enabled?'default':'destructive',onPress:async()=>{
    const id=item['.id'];
    if(!id)return Alert.alert('Gagal','ID interface tidak tersedia.');
    setInterfaceBusy(true);
    try{
      await api(`/api/router/interfaces/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({enabled})});
      const updated={...item,disabled:String(!enabled)};
      setDetailItem(current=>current?.type==='interface'&&current.item['.id']===id?{...current,item:updated}:current);
      await loadData('router',true);
      Alert.alert('Berhasil',`Interface ${enabled?'diaktifkan':'dinonaktifkan'}.`);
    }catch(e){Alert.alert('Gagal mengubah interface',e.message);}finally{setInterfaceBusy(false);}
  }}]);

  const dashboardScreen=()=>{
    const d=data.dashboard;
    return <ScrollView contentContainerStyle={styles.pageContent} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={C.blue}/> }>
      {error?<Card style={styles.errorCard}><Text style={styles.errorTitle}>Gagal memuat data router</Text><Text style={styles.errorText}>{error}</Text><Button title="Coba lagi" kind="secondary" onPress={refresh}/></Card>:null}
      <Card style={styles.routerSummary}><View style={styles.routerMark}><AppIcon name="router" color={C.cyan} size={25}/></View><View style={{flex:1}}><View style={styles.inline}><Text style={[styles.routerStatus,error&&{color:C.red}]}>Router {error?'Offline':d.identity?'Online':'Menghubungkan'}</Text>{d.identity&&!error?<View style={styles.onlineDot}/>:null}</View><Text style={styles.routerName}>{d.identity||routers[0]?.name|| (loading?'Memuat data router...':'Data router belum tersedia')}</Text><Text style={styles.routerMeta}>{[d.boardName,d.version,routers[0]?.host].filter(Boolean).join('  ·  ')||DASH}</Text></View><Text style={styles.tag}>{d.version||DASH}</Text></Card>
      <View style={styles.statsGrid}>
        <StatCard label="PPP Aktif" value={d.active} sub={d.totalSecrets===undefined?undefined:`/ ${d.totalSecrets}`} icon="users" tone={C.purple} onPress={()=>{setPppView('active');setTab('ppp');}}/>
        <StatCard label="Total Secret" value={d.totalSecrets} icon="user" tone={C.blue} onPress={()=>setTab('ppp')}/>
        <StatCard label="Hotspot Aktif" value={d.activeHotspot} sub="terhubung" icon="voucher" tone={C.cyan} onPress={()=>{setHotspotView('vouchers');setTab('hotspot');}}/>
        <StatCard label="Uptime" value={d.uptime} sub="router aktif" icon="clock" tone={C.purple} compactValue/>
      </View>
      <Card style={styles.trafficCard}><View style={styles.rowBetween}><View><Text style={styles.cardTitle}>Trafik Realtime</Text><Text style={styles.cardSubtitle}>{d.activeInterfaces??DASH} interface aktif</Text></View><Pill tone={trafficStatus==='live'?C.green:trafficStatus==='error'?C.red:C.muted}>{trafficStatus==='live'?'Live':trafficStatus==='error'?'Error':'Menunggu'}</Pill></View><Dropdown triggerLabel="Ganti interface" value={selectedTrafficInterface} options={trafficInterfaceOptions(data.interfaces)} onChange={name=>{trafficGeneration.current+=1;previousTraffic.current=null;setTrafficHistory([]);setTrafficStatus('loading');setTrafficError('');setData(current=>({...current,dashboard:{...current.dashboard,traffic:{rx:null,tx:null,ready:false}}}));setSelectedTrafficInterface(name);}} placeholder="Pilih interface"/><TrafficChart history={trafficHistory} status={trafficStatus}/>{trafficStatus==='error'&&trafficError?<Text style={styles.trafficError}>{trafficError}</Text>:null}<View style={styles.trafficFooter}><View><Text style={styles.cardSubtitle}>Download</Text><Text style={styles.rateValue}>{formatRate(d.traffic?.rx)}</Text></View><View><Text style={styles.cardSubtitle}>Upload</Text><Text style={[styles.rateValue,{color:C.purple}]}>{formatRate(d.traffic?.tx)}</Text></View></View></Card>
      <View style={styles.statsGrid}><StatCard label="CPU" value={d.cpuLoad===undefined?null:`${d.cpuLoad}%`} sub="Pemakaian router" icon="cpu" tone={C.green}/><StatCard label="Memory" value={d.memoryUsedPercent===undefined?null:`${d.memoryUsedPercent}%`} sub={d.freeMemory?`${d.freeMemory} tersedia`:''} icon="memory" tone={C.purple}/></View>
    </ScrollView>;
  };

  const pppScreen=()=>{
    if(pppView==='profileForm')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title={pppProfileEdit?'Edit Profile PPP':'Tambah Profile PPP'} subtitle="Profile utama disimpan ke RouterOS." right={<Pressable onPress={()=>setPppView('users')}><Text style={styles.link}>Batal</Text></Pressable>}/><View style={styles.chipRow}><Chip label="General" selected={pppProfileTab==='general'} onPress={()=>setPppProfileTab('general')}/><Chip label="Protocols" selected={pppProfileTab==='protocols'} onPress={()=>setPppProfileTab('protocols')}/><Chip label="Limits" selected={pppProfileTab==='limits'} onPress={()=>setPppProfileTab('limits')}/></View><Card>{pppProfileTab==='general'?<><Field label="COMMENT" value={pppProfileForm.comment} onChangeText={comment=>setPppProfileForm(current=>({...current,comment}))} placeholder="Komentar profile (opsional)"/><Field label="NAME" value={pppProfileForm.name} onChangeText={name=>setPppProfileForm(current=>({...current,name}))} placeholder="Nama profile"/>{pppProfileAddressFields.local?<PppAddressField label="LOCAL ADDRESS" value={pppProfileForm.localAddress} pools={pppAddressPools} onChange={localAddress=>setPppProfileForm(current=>({...current,localAddress}))} optional onVisibilityChange={local=>setPppProfileAddressFields(current=>({...current,local}))}/>:<Pressable accessibilityRole="button" accessibilityLabel="Tambah Local Address" onPress={()=>setPppProfileAddressFields(current=>({...current,local:true}))} style={styles.pppProfileAddField}><Text style={styles.pppProfileAddText}>＋  Local Address</Text></Pressable>}{pppProfileAddressFields.remote?<PppAddressField label="REMOTE ADDRESS" value={pppProfileForm.remoteAddress} pools={pppAddressPools} onChange={remoteAddress=>setPppProfileForm(current=>({...current,remoteAddress}))} optional onVisibilityChange={remote=>setPppProfileAddressFields(current=>({...current,remote}))}/>:<Pressable accessibilityRole="button" accessibilityLabel="Tambah Remote Address" onPress={()=>setPppProfileAddressFields(current=>({...current,remote:true}))} style={styles.pppProfileAddField}><Text style={styles.pppProfileAddText}>＋  Remote Address</Text></Pressable>}<Field label="DNS SERVER" value={pppProfileForm.dnsServer} onChangeText={dnsServer=>setPppProfileForm(current=>({...current,dnsServer}))} placeholder="Opsional"/><Field label="WINS SERVER" value={pppProfileForm.winsServer} onChangeText={winsServer=>setPppProfileForm(current=>({...current,winsServer}))} placeholder="Opsional"/><ChoiceField label="CHANGE TCP MSS" value={pppProfileForm.changeTcpMss} options={['no','yes','default']} onChange={changeTcpMss=>setPppProfileForm(current=>({...current,changeTcpMss}))}/><ChoiceField label="USE UPnP" value={pppProfileForm.useUpnp} options={['no','yes','default']} onChange={useUpnp=>setPppProfileForm(current=>({...current,useUpnp}))}/></>:pppProfileTab==='protocols'?<><ChoiceField label="USE IPv6" value={pppProfileForm.useIpv6} options={['no','yes','required','default']} onChange={useIpv6=>setPppProfileForm(current=>({...current,useIpv6}))}/><ChoiceField label="USE MPLS" value={pppProfileForm.useMpls} options={['no','yes','required','default']} onChange={useMpls=>setPppProfileForm(current=>({...current,useMpls}))}/><ChoiceField label="USE COMPRESSION" value={pppProfileForm.useCompression} options={['no','yes','default']} onChange={useCompression=>setPppProfileForm(current=>({...current,useCompression}))}/><ChoiceField label="USE ENCRYPTION" value={pppProfileForm.useEncryption} options={['no','yes','required','default']} onChange={useEncryption=>setPppProfileForm(current=>({...current,useEncryption}))}/></>:<><View style={styles.pppLimits}><OptionalLimitRow label="Session Timeout" value={pppProfileForm.sessionTimeout} onChange={sessionTimeout=>setPppProfileForm(current=>({...current,sessionTimeout}))} placeholder="1h"/><OptionalLimitRow label="Idle Timeout" value={pppProfileForm.idleTimeout} onChange={idleTimeout=>setPppProfileForm(current=>({...current,idleTimeout}))} placeholder="5m"/><OptionalLimitRow label="Rate Limit (rx/tx)" value={pppProfileForm.rateLimit} onChange={rateLimit=>setPppProfileForm(current=>({...current,rateLimit}))} placeholder="15M/15M"/><ChoiceField inline label="Only One" value={pppProfileForm.onlyOne} options={['no','yes','default']} onChange={onlyOne=>setPppProfileForm(current=>({...current,onlyOne}))}/></View></>}<Button title={saving?'Menyimpan...':pppProfileEdit?'Simpan Perubahan':'Tambah Profile'} disabled={saving} onPress={savePppProfile}/></Card></ScrollView>;
    if(pppView==='add')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title={pppEditId?'Edit Akun PPP':'Tambah Akun PPP'} subtitle="Perubahan disimpan langsung di MikroTik." right={<Pressable onPress={()=>{setPppEditId(null);setPppView('users');}}><Text style={styles.link}>Batal</Text></Pressable>}/><Card><Field label="USERNAME" value={pppForm.name} onChangeText={name=>setPppForm(current=>({...current,name}))} placeholder="Username pelanggan"/><Field label={pppEditId?'PASSWORD BARU (OPSIONAL)':'PASSWORD'} value={pppForm.password} onChangeText={password=>setPppForm(current=>({...current,password}))} placeholder={pppEditId?'Kosongkan jika tidak diubah':'Password PPP'} secure revealable/><Dropdown label="SERVICE" value={pppForm.service} options={data.services.map(service=>({value:service.value,label:service.label.toUpperCase()}))} onChange={service=>setPppForm(current=>({...current,service}))}/><Dropdown label="PROFILE" value={pppForm.profile} options={data.profiles.map(profile=>({value:profile.name,label:profile.name}))} onChange={profile=>setPppForm(current=>({...current,profile}))} placeholder="Pilih profile" inlineOptions optionLimit={5}/>{!data.profiles.length?<Text style={styles.cardSubtitle}>Profile belum tersedia dari RouterOS.</Text>:null}<PppAddressField label="LOCAL ADDRESS (OPSIONAL)" value={pppForm.localAddress} pools={pppAddressPools} onChange={localAddress=>setPppForm(current=>({...current,localAddress}))}/><PppAddressField label="REMOTE ADDRESS (OPSIONAL)" value={pppForm.remoteAddress} pools={pppAddressPools} onChange={remoteAddress=>setPppForm(current=>({...current,remoteAddress}))}/><Field label="COMMENT (OPSIONAL)" value={pppForm.comment} onChangeText={comment=>setPppForm(current=>({...current,comment}))} placeholder="Catatan akun"/><Button title={saving?(pppEditId?'Menyimpan...':'Menambahkan...'):pppEditId?'Simpan Perubahan':'Simpan Akun'} disabled={saving||!data.profiles.length} onPress={savePpp}/></Card></ScrollView>;
    return <View style={styles.flex}><View style={styles.pageContent}><ScreenHeader title={pppView==='active'?'PPP Aktif':pppFilter==='profile'?'Profile PPP':'PPP'} subtitle={pppView==='active'?'Koneksi online':pppFilter==='profile'?'Daftar profile PPP':'Daftar akun PPPoE'} right={pppFilter==='profile'?<Pressable onPress={()=>openPppProfileForm()} style={styles.addButton}><Text style={styles.addButtonText}>+</Text></Pressable>:pppView==='users'?<Pressable onPress={()=>{setPppEditId(null);setPppForm({name:'',password:'',service:'pppoe',profile:data.profiles[0]?.name||'',localAddress:'',remoteAddress:'',comment:''});setPppView('add');}} style={styles.addButton}><Text style={styles.addButtonText}>+</Text></Pressable>:<Pressable onPress={()=>{setPppView('users');setPppFilter('all');}}><Text style={styles.link}>Daftar akun</Text></Pressable>}/><View style={styles.searchBox}><AppIcon name="search" color={C.muted} size={15}/><TextInput value={search} onChangeText={setSearch} placeholder={pppFilter==='profile'?'Cari profile...':pppView==='active'?'Cari user atau IP...':'Cari username...'} placeholderTextColor={C.muted} style={styles.searchInput}/></View>{pppView==='users'?<View style={styles.chipRow}><Chip label={`Semua (${data.secrets.length})`} selected={pppFilter==='all'} onPress={()=>setPppFilter('all')}/><Chip label={`Aktif (${data.active.length})`} selected={pppFilter==='active'} onPress={()=>setPppFilter('active')}/><Chip label={`Offline (${Math.max(0,data.secrets.length-data.active.length)}`} selected={pppFilter==='offline'} onPress={()=>setPppFilter('offline')}/><Chip label={`Profile (${data.profiles.length})`} selected={pppFilter==='profile'} onPress={()=>setPppFilter('profile')}/></View>:null}</View><FlatList data={pppView==='active'?visibleActive:pppFilter==='profile'?visibleProfiles:visibleSecrets} keyExtractor={(item,index)=>String(item['.id']||item.name||index)} contentContainerStyle={styles.listContent} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={C.blue}/>} renderItem={({item})=>{
      if(pppFilter==='profile'&&pppView!=='active'){
        return <Card onPress={()=>showPppProfileDetail(item)} style={styles.userCard}><View style={styles.userRow}><View style={[styles.userAvatar,{backgroundColor:`${C.purple}24`}]}><AppIcon name="settings" color={C.purple} size={18}/></View><View style={{flex:1}}><View style={styles.rowBetween}><Text style={styles.cardTitle}>{item.name||'Tanpa nama'}</Text>{item['only-one']?<Pill tone={item['only-one']==='yes'?C.green:C.muted}>{`Only-one: ${item['only-one']}`}</Pill>:item.default==='true'?<Pill tone={C.cyan}>Default</Pill>:null}</View><Text style={styles.cardSubtitle}>{`Local: ${item['local-address']||DASH} · Remote: ${item['remote-address']||DASH}`}</Text><Text style={styles.cardSubtitle}>{`Rate limit: ${item['rate-limit']||DASH}${item['dns-server']?` · DNS: ${item['dns-server']}`:''}`}</Text></View></View>{item.comment?<View style={styles.userFooter}><Text style={styles.cardSubtitle}>{item.comment}</Text></View>:null}</Card>;
      }
      const active=pppView==='active'||activeNames.has(item.name);
      return <Card onPress={pppView==='users'?()=>showPppActions(item):undefined} style={styles.userCard}><View style={styles.userRow}><View style={[styles.userAvatar,{backgroundColor:active?`${C.blue}30`:`${C.purple}24`}]}><AppIcon name="user" color={active?C.cyan:C.purple} size={18}/></View><View style={{flex:1}}><View style={styles.rowBetween}><Text style={styles.cardTitle}>{item.name||'Tanpa username'}</Text><Pill tone={active?C.green:C.muted}>{active?'Online':'Offline'}</Pill></View><Text style={styles.cardSubtitle}>{pppView==='active'?(item.address||DASH):`Profil ${item.profile||DASH} · ${item.service||'pppoe'}`}</Text>{pppView==='active'?<Text style={styles.cardSubtitle}>Uptime {formatUptime(item.uptime)} · Caller {item['caller-id']||DASH}</Text>:null}</View></View><View style={styles.userFooter}><Text style={styles.cardSubtitle}>{pppView==='active'?'Koneksi PPP aktif':`Remote address ${item['remote-address']||DASH}`}</Text>{pppView==='active'?<Button title="Putuskan" kind="danger" compact onPress={()=>disconnectPpp(item)}/>:null}</View></Card>;
    }} ListEmptyComponent={<EmptyState title={loading?'Memuat akun...':pppView==='active'?'Tidak ada sesi aktif':pppFilter==='profile'?'Profile belum tersedia':'Akun belum tersedia'} detail={error||'Data akan tampil setelah berhasil dimuat dari MikroTik.'} loading={loading}/>} /></View>;
  };

  const hotspotScreen=()=>{
    if(hotspotView==='voucher')return <ScrollView contentContainerStyle={styles.pageContent} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={()=>loadData('hotspot',true)} tintColor={C.blue}/> }><ScreenHeader title="Vouchers" subtitle="Voucher dikelompokkan berdasarkan profile." right={<Pressable onPress={()=>loadData('hotspot',true)}><AppIcon name="refresh" color={C.cyan} size={20}/></Pressable>}/><View style={styles.chipRow}><Chip label={`Daftar User (${data.hotspotUsers.length})`} selected={false} tone={C.cyan} onPress={()=>{setHotspotProfileFilter('all');setHotspotView('vouchers');}}/><Chip label={`User Aktif (${data.hotspotActive.length})`} selected={false} tone={C.cyan} onPress={()=>setHotspotView('active')}/><Chip label="Voucher" selected tone={C.cyan} onPress={()=>setHotspotView('voucher')}/><Chip label="Setting" selected={false} tone={C.cyan} onPress={()=>setHotspotView('profiles')}/></View>{[{name:'all'},...data.hotspotProfiles].map((profile,index)=>{const count=profile.name==='all'?data.hotspotUsers.length:data.hotspotUsers.filter(user=>user.profile===profile.name).length;return <View key={profile['.id']||profile.name} style={[styles.voucherProfileCard,{backgroundColor:index===0||count>0?C.cyan:'#768391'}]}><View style={styles.voucherProfileIcon}><AppIcon name="voucher" color="#fff" size={32}/></View><View style={styles.voucherProfileContent}><Text style={styles.voucherProfileTitle}>Profile : {profile.name}</Text><Text style={styles.voucherProfileCount}>{count} {count===1?'Item':'Items'}</Text><View style={styles.voucherProfileActions}><Pressable onPress={()=>{setHotspotProfileFilter(profile.name);setHotspotView('vouchers');}} style={styles.voucherProfileAction}><AppIcon name="interface" color="#fff" size={14}/><Text style={styles.voucherProfileActionText}>Open</Text></Pressable><Pressable onPress={()=>{setVoucherForm(current=>({...current,profile:profile.name==='all'?(current.profile||data.hotspotProfiles[0]?.name||''):profile.name}));setHotspotView('generate');}} style={styles.voucherProfileAction}><AppIcon name="users" color="#fff" size={14}/><Text style={styles.voucherProfileActionText}>Generate</Text></Pressable></View></View></View>;})}{!data.hotspotProfiles.length?<Text style={styles.cardSubtitle}>Profile Hotspot tidak tersedia pada router.</Text>:null}</ScrollView>;
    if(hotspotView==='addUser')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title="Add User" subtitle="Tambah satu user langsung ke RouterOS." right={<Pressable onPress={()=>setHotspotView('vouchers')}><Text style={styles.link}>Tutup</Text></Pressable>}/><Card><Dropdown label="SERVER" value={hotspotUserForm.server} options={[{value:'all',label:'all'},...data.hotspotServers.map(server=>({value:server.name,label:server.name}))]} onChange={server=>setHotspotUserForm(current=>({...current,server}))}/><Field label="NAME" value={hotspotUserForm.name} onChangeText={name=>setHotspotUserForm(current=>({...current,name}))} placeholder="Username user"/><Field label="PASSWORD" value={hotspotUserForm.password} onChangeText={password=>setHotspotUserForm(current=>({...current,password}))} placeholder="Password (opsional)" secure/><Dropdown label="PROFILE" value={hotspotUserForm.profile} options={data.hotspotProfiles.map(profile=>({value:profile.name,label:profile.name}))} onChange={profile=>setHotspotUserForm(current=>({...current,profile}))} placeholder="Pilih profile"/><Field label="TIME LIMIT" value={hotspotUserForm.duration} onChangeText={duration=>setHotspotUserForm(current=>({...current,duration}))} placeholder="Kosongkan tanpa batas, contoh 1h"/><Field label="DATA LIMIT (MB)" value={hotspotUserForm.limitBytesTotal} onChangeText={limitBytesTotal=>setHotspotUserForm(current=>({...current,limitBytesTotal}))} placeholder="Opsional" keyboardType="decimal-pad"/><Field label="COMMENT" value={hotspotUserForm.comment} onChangeText={comment=>setHotspotUserForm(current=>({...current,comment}))} placeholder="Catatan user"/><Button title={saving?'Menyimpan...':'Simpan User'} disabled={saving||!data.hotspotProfiles.length} onPress={saveHotspotUser}/></Card></ScrollView>;
    if(hotspotView==='profileForm')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title={profileEditing?'Edit User Profile':'Add User Profile'} subtitle="Profile utama disimpan ke RouterOS." right={<Pressable onPress={()=>setHotspotView('profiles')}><Text style={styles.link}>Tutup</Text></Pressable>}/><Card><Field label="NAME" value={profileForm.name} onChangeText={name=>setProfileForm(current=>({...current,name}))} placeholder="Nama profile"/><Dropdown label="ADDRESS POOL" value={profileForm['address-pool']} options={[{value:'none',label:'none'},...data.hotspotAddressPools.map(pool=>({value:pool.name,label:pool.name}))]} onChange={value=>setProfileForm(current=>({...current,'address-pool':value}))}/><Field label="SHARED USERS" value={profileForm['shared-users']} onChangeText={value=>setProfileForm(current=>({...current,'shared-users':value}))} placeholder="1" keyboardType="number-pad"/><Field label="RATE LIMIT [UP/DOWN]" value={profileForm['rate-limit']} onChangeText={value=>setProfileForm(current=>({...current,'rate-limit':value}))} placeholder="Example: 512k/1M"/><Dropdown label="EXPIRED MODE" value={profileForm.expiredMode} options={[{value:'',label:'Select...'},...[['none','None'],['remove','Remove'],['notice','Notice'],['remove-record','Remove & Record'],['notice-record','Notice & Record']].map(([value,label])=>({value,label}))]} onChange={expiredMode=>setProfileForm(current=>({...current,expiredMode}))}/><Field label="VALIDITY" value={profileForm.validity} onChangeText={validity=>setProfileForm(current=>({...current,validity}))} placeholder="Contoh: 1d, 1w, 30d"/><Field label="PRICE RP" value={profileForm.price} onChangeText={price=>setProfileForm(current=>({...current,price}))} placeholder="Harga modal" keyboardType="number-pad"/><Field label="SELLING PRICE RP" value={profileForm.sellingPrice} onChangeText={sellingPrice=>setProfileForm(current=>({...current,sellingPrice}))} placeholder="Harga jual" keyboardType="number-pad"/><Dropdown label="LOCK USER" value={profileForm.lockUser} options={[{value:'disable',label:'Disable'},{value:'enable',label:'Enable'}]} onChange={lockUser=>setProfileForm(current=>({...current,lockUser}))}/><Dropdown label="PARENT QUEUE" value={profileForm['parent-queue']} options={[{value:'none',label:'none'},...data.queues.map(queue=>({value:queue.name,label:queue.name}))]} onChange={value=>setProfileForm(current=>({...current,'parent-queue':value}))}/><Button title={saving?'Menyimpan...':'Simpan Profile'} disabled={saving} onPress={saveHotspotProfile}/></Card></ScrollView>;
    if(hotspotView==='generate')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title="Generate Voucher" subtitle="Atur kode lalu buat user Hotspot di MikroTik." right={<Pressable onPress={()=>setHotspotView('vouchers')}><Text style={styles.link}>Tutup</Text></Pressable>}/><Card><Field label="QTY" value={voucherForm.count} onChangeText={count=>setVoucherForm(current=>({...current,count}))} placeholder="1" keyboardType="number-pad"/><Dropdown label="SERVER" value={voucherForm.server} options={[{value:'all',label:'all'},...data.hotspotServers.map(server=>({value:server.name,label:server.name}))]} onChange={server=>setVoucherForm(current=>({...current,server}))} placeholder="Pilih server"/><Dropdown label="USER MODE" value={voucherForm.userMode} options={[{value:'username',label:'Username saja'},{value:'usernamePassword',label:'Username dan password sama'}]} onChange={userMode=>setVoucherForm(current=>({...current,userMode}))}/><Field label="NAME LENGTH" value={voucherForm.nameLength} onChangeText={nameLength=>setVoucherForm(current=>({...current,nameLength}))} placeholder="4" keyboardType="number-pad"/><Field label="PREFIX" value={voucherForm.prefix} onChangeText={prefix=>setVoucherForm(current=>({...current,prefix}))} placeholder="Opsional, mis. WIFI-"/><Field label="CHARACTER" value={voucherForm.characters} onChangeText={characters=>setVoucherForm(current=>({...current,characters}))} placeholder="Huruf dan angka"/><Dropdown label="PROFILE" value={voucherForm.profile} options={data.hotspotProfiles.map(profile=>({value:profile.name,label:profile.name}))} onChange={profile=>setVoucherForm(current=>({...current,profile}))} placeholder="Pilih profil" optionLimit={5}/><Field label="TIME LIMIT" value={voucherForm.duration} onChangeText={duration=>setVoucherForm(current=>({...current,duration}))} placeholder="1h, 1d, 1w"/><Field label="DATA LIMIT (MB)" value={voucherForm.limitBytesTotal} onChangeText={limitBytesTotal=>setVoucherForm(current=>({...current,limitBytesTotal}))} placeholder="Kosongkan tanpa batas" keyboardType="decimal-pad"/><Field label="COMMENT" value={voucherForm.comment} onChangeText={comment=>setVoucherForm(current=>({...current,comment}))} placeholder="Catatan voucher"/><Button title={saving?'Membuat voucher...':'Generate Voucher'} disabled={saving||!data.hotspotProfiles.length} onPress={generateVouchers}/></Card></ScrollView>;
    if(hotspotView==='generated')return <ScrollView contentContainerStyle={styles.pageContent}><ScreenHeader title="Voucher berhasil dibuat" subtitle={`${generatedVouchers.length} voucher · ${generatedVoucherMeta.profile} · ${generatedVoucherMeta.duration}`} right={<Pressable onPress={()=>setHotspotView('vouchers')}><Text style={styles.link}>Kembali</Text></Pressable>}/><View style={styles.chipRow}><Button title={'Default A4 · '+generatedVouchers.length+' Voucher'} onPress={printGeneratedVouchers}/><Button title="Bagikan PDF" kind="secondary" onPress={shareGeneratedVouchers}/></View><Text style={styles.cardSubtitle}>PDF berisi username dan password untuk dibagikan atau dicetak. Simpan dengan aman karena data ini memberi akses ke jaringan.</Text>{generatedVouchers.map((item,index)=><Card key={`${item.name}-${index}`} style={styles.userCard}><View style={styles.rowBetween}><Text style={styles.cardTitle}>Voucher {String(index+1).padStart(3,'0')}</Text><Pill tone={C.green}>Baru</Pill></View><Text style={styles.cardSubtitle}>Username: {item.name}</Text><Text style={styles.cardSubtitle}>Password: {item.password}</Text><Text style={styles.cardSubtitle}>Profil {item.profile||generatedVoucherMeta.profile} · Durasi {item['limit-uptime']||generatedVoucherMeta.duration}</Text></Card>)}</ScrollView>;
    if(hotspotView==='edit')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title="Edit Voucher Hotspot" subtitle="Perubahan disimpan langsung di MikroTik." right={<Pressable onPress={()=>setHotspotView('vouchers')}><Text style={styles.link}>Batal</Text></Pressable>}/><Card><Field label="USERNAME" value={hotspotEditForm.name} onChangeText={name=>setHotspotEditForm(current=>({...current,name}))} placeholder="Username voucher"/><Field label="PASSWORD BARU (OPSIONAL)" value={hotspotEditForm.password} onChangeText={password=>setHotspotEditForm(current=>({...current,password}))} placeholder="Kosongkan jika tidak diubah" secure/><Dropdown label="PROFILE" value={hotspotEditForm.profile} options={data.hotspotProfiles.map(profile=>({value:profile.name,label:profile.name}))} onChange={profile=>setHotspotEditForm(current=>({...current,profile}))}/><Field label="DURASI (OPSIONAL)" value={hotspotEditForm.duration} onChangeText={duration=>setHotspotEditForm(current=>({...current,duration}))} placeholder="Contoh: 1h, 1d"/><Field label="COMMENT (OPSIONAL)" value={hotspotEditForm.comment} onChangeText={comment=>setHotspotEditForm(current=>({...current,comment}))} placeholder="Catatan voucher"/><Button title={saving?'Menyimpan...':'Simpan Perubahan'} disabled={saving||!data.hotspotProfiles.length} onPress={saveVoucher}/></Card></ScrollView>;
    if(hotspotView==='generate')return <ScrollView contentContainerStyle={styles.pageContent} keyboardShouldPersistTaps="handled"><ScreenHeader title="Buat Voucher" subtitle="Voucher disimpan sebagai user Hotspot di MikroTik." right={<Pressable onPress={()=>setHotspotView('vouchers')}><Text style={styles.link}>Batal</Text></Pressable>}/><Card><Field label="JUMLAH VOUCHER" value={voucherForm.count} onChangeText={count=>setVoucherForm(current=>({...current,count}))} placeholder="Jumlah, maksimal 100" keyboardType="number-pad"/><Field label="DURASI" value={voucherForm.duration} onChangeText={duration=>setVoucherForm(current=>({...current,duration}))} placeholder="1h, 1d, 1w"/><Text style={styles.label}>PROFILE HOTSPOT</Text><View style={styles.optionList}>{data.hotspotProfiles.map(profile=><Chip key={profile['.id']||profile.name} label={profile.name} selected={voucherForm.profile===profile.name} onPress={()=>setVoucherForm(current=>({...current,profile:profile.name}))}/>)}</View>{!data.hotspotProfiles.length?<Text style={styles.cardSubtitle}>Profile Hotspot tidak tersedia pada router.</Text>:null}<Button title={saving?'Membuat voucher...':'Generate Voucher'} disabled={saving||!data.hotspotProfiles.length} onPress={generateVouchers}/></Card></ScrollView>;
    const list=hotspotView==='active'?data.hotspotActive:hotspotView==='profiles'?data.hotspotProfiles:data.hotspotUsers;
    const comments=[...new Set(data.hotspotUsers.map(item=>item.comment).filter(Boolean))];
    const matchesSearch=item=>(String(item.name||'')+' '+String(item.profile||'')+' '+String(item.comment||'')).toLowerCase().includes(search.toLowerCase());
    const visibleList=hotspotView==='vouchers'?data.hotspotUsers.filter(item=>(hotspotProfileFilter==='all'||item.profile===hotspotProfileFilter)&&(hotspotCommentFilter==='all'||(item.comment||'')===hotspotCommentFilter)&&matchesSearch(item)):list;
    return <View style={styles.flex}><ScrollView contentContainerStyle={styles.pageContent} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={C.blue}/> }><ScreenHeader title="Hotspot" subtitle="Voucher dan manajemen Hotspot" right={<Pressable onPress={()=>loadData('hotspot',true)}><Text style={styles.link}>Muat ulang</Text></Pressable>}/><View style={styles.chipRow}><Chip label={'Daftar User ('+data.hotspotUsers.length+')'} selected={hotspotView==='vouchers'} tone={C.cyan} onPress={()=>{setHotspotProfileFilter('all');setHotspotCommentFilter('all');setHotspotView('vouchers');}}/><Chip label={'User Aktif ('+data.hotspotActive.length+')'} selected={hotspotView==='active'} tone={C.cyan} onPress={()=>setHotspotView('active')}/><Chip label="Voucher" selected={hotspotView==='voucher'} tone={C.cyan} onPress={()=>setHotspotView('voucher')}/><Chip label="Setting" selected={hotspotView==='profiles'} tone={C.cyan} onPress={()=>setHotspotView('profiles')}/></View>{hotspotView==='vouchers'?<><View style={styles.sectionHeading}><Text style={styles.sectionTitle}>{'Daftar User ('+data.hotspotUsers.length+')'}</Text><Button title="Add User" compact onPress={()=>{setHotspotUserForm(current=>({...current,profile:current.profile||data.hotspotProfiles[0]?.name||''}));setHotspotView('addUser');}}/></View><Field label="CARI USER" value={search} onChangeText={setSearch} placeholder="Search"/><View style={{flexDirection:"row",gap:8}}><Dropdown inlineOptions label="PROFILE" value={hotspotProfileFilter} options={[{value:'all',label:'Semua Profile'},...data.hotspotProfiles.map(profile=>({value:profile.name,label:profile.name}))]} onChange={setHotspotProfileFilter} style={{flex:1,minWidth:120}}/><Dropdown inlineOptions label="COMMENT" value={hotspotCommentFilter} options={[{value:'all',label:'Semua Comment'},...comments.map(comment=>({value:comment,label:comment}))]} onChange={setHotspotCommentFilter} style={{flex:1,minWidth:120}}/></View><View style={styles.chipRow}><Button title="Default A4" compact onPress={()=>printHotspotList('default')}/><Button title="QR A4" compact kind="secondary" onPress={()=>printHotspotList('qr')}/><Button title="Small Struk" compact kind="secondary" onPress={()=>printHotspotList('small')}/></View></>:<View style={styles.sectionHeading}><Text style={styles.sectionTitle}>{hotspotView==='active'?'User Aktif':'Profile Hotspot'}</Text>{hotspotView==='profiles'?<Pressable accessibilityRole="button" accessibilityLabel="Tambah profil Hotspot" onPress={()=>openProfileForm()} style={styles.addButton}><AppIcon name="plus" color="#fff" size={20}/></Pressable>:null}</View>}{visibleList.map((item,index)=><Card key={item['.id']||item.name||item.user||index} onPress={hotspotView==='vouchers'?()=>showVoucherActions(item):hotspotView==='profiles'?()=>openProfileDetail(item):undefined} style={styles.userCard}><View style={styles.userRow}><View style={[styles.userAvatar,{backgroundColor:hotspotView==='active'?C.green+'22':C.cyan+'22'}]}><AppIcon name={hotspotView==='active'?'user':hotspotView==='profiles'?'settings':'voucher'} color={hotspotView==='active'?C.green:C.cyan} size={17}/></View><View style={{flex:1}}><View style={styles.rowBetween}><Text style={styles.cardTitle}>{item.name||item.user||'Hotspot user'}</Text>{hotspotView!=='profiles'?<Pill tone={item.disabled==='true'?C.red:C.green}>{item.disabled==='true'?'Disabled':hotspotView==='active'?'Online':'Tersedia'}</Pill>:null}</View><Text style={styles.cardSubtitle}>{hotspotView==='active'?(item.address||DASH)+' - '+(item['mac-address']||DASH):hotspotView==='profiles'?['rate-limit','shared-users'].filter(key=>item[key]!==undefined&&item[key]!==null&&item[key]!=='').map(key=>(key==='rate-limit'?'Rate':'Shared')+' '+item[key]).join(' - ')||'Tekan untuk melihat detail':'Profil '+(item.profile||DASH)+' - Durasi '+(item['limit-uptime']||DASH)}</Text>{hotspotView==='active'?<Text style={styles.cardSubtitle}>Uptime {formatUptime(item.uptime)} - Server {item.server||DASH}</Text>:null}</View></View></Card>)}{!visibleList.length?<EmptyState title={loading?'Memuat data...':hotspotView==='active'?'Tidak ada user aktif':hotspotView==='profiles'?'Profile belum tersedia':'Belum ada user'} detail={error||'Belum ada data yang dikirim router MikroTik.'} loading={loading}/>:null}</ScrollView></View>;
  };

  const routerScreen=()=>{
    const d=data.dashboard;
    return <ScrollView contentContainerStyle={styles.pageContent} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={refresh} tintColor={C.blue}/> }><ScreenHeader title="Router" subtitle="Informasi MikroTik"/>{error?<Card style={styles.errorCard}><Text style={styles.errorText}>{error}</Text><Button title="Coba lagi" kind="secondary" onPress={refresh}/></Card>:null}<Card style={styles.routerSummary}><View style={styles.routerMark}><AppIcon name="router" color={C.cyan} size={25}/></View><View style={{flex:1}}><Text style={styles.routerName}>{d.identity||routers[0]?.name||DASH}</Text><Text style={styles.cardSubtitle}>{routers[0]?.host||DASH}</Text><Text style={styles.cardSubtitle}>RouterOS {d.version||DASH}</Text></View><Pill tone={d.identity?C.green:C.muted}>{d.identity?'Online':'Status'}</Pill></Card><Card><SectionTitle title="Perangkat"/><Text style={styles.cardTitle}>{d.boardName||DASH}</Text><Text style={styles.cardSubtitle}>Arsitektur {d.architecture||DASH}</Text></Card><View style={styles.statsGrid}><StatCard label="CPU" value={d.cpuLoad===undefined?null:`${d.cpuLoad}%`} tone={C.green} icon="cpu"/><StatCard label="Memory" value={d.memoryUsedPercent===undefined?null:`${d.memoryUsedPercent}%`} sub={d.freeMemory?`${d.freeMemory} free`:''} tone={C.purple} icon="memory"/><StatCard label="Uptime" value={d.uptime} tone={C.blue} compactValue icon="clock" compactValue/><StatCard label="Interface" value={d.totalInterfaces} sub="terdeteksi" tone={C.cyan} icon="interface"/></View><Card><SectionTitle title="Interface" action="Muat ulang" onAction={refresh}/>{data.interfaces.map((item,index)=><Pressable accessibilityRole="button" accessibilityLabel={`Detail interface ${item.name||index+1}`} key={item['.id']||item.name||index} onPress={()=>setDetailItem({type:'interface',item})} style={styles.interfaceRow}><View style={[styles.interfaceMark,{backgroundColor:item.running==='true'?`${C.green}22`:`${C.muted}20`}]}><AppIcon name="interface" color={item.running==='true'?C.green:C.muted} size={16}/></View><View style={{flex:1}}><Text style={styles.cardTitle}>{item.name||`Interface ${index+1}`}</Text><Text style={styles.cardSubtitle}>{item.type||'interface'} · {item.running==='true'?'Connected':'Disabled'}</Text></View><View style={[styles.onlineDot,{backgroundColor:item.running==='true'?C.green:C.muted}]}/></Pressable>)}{!data.interfaces.length?<EmptyState title="Interface belum tersedia" detail={error||'Interface router akan muncul di sini.'} loading={loading}/>:null}</Card><Card style={styles.trafficFooterCard}><Text style={styles.cardTitle}>Traffic</Text><View style={styles.trafficFooter}><View><Text style={styles.cardSubtitle}>RX / Download</Text><Text style={styles.rateValue}>{formatRate(d.traffic?.rx)}</Text></View><View><Text style={styles.cardSubtitle}>TX / Upload</Text><Text style={[styles.rateValue,{color:C.purple}]}>{formatRate(d.traffic?.tx)}</Text></View></View></Card></ScrollView>;
  };

  const showSettingInfo=(title,message)=>Alert.alert(title,message);
  const toggleDarkMode=async()=>{const enabled=!darkMode;applyThemeStyles(enabled);setDarkMode(enabled);try{await AsyncStorage.setItem(THEME_SETTINGS_KEY,enabled?'dark':'light');}catch(e){Alert.alert('Gagal menyimpan tema',e.message||'Preferensi tema tidak dapat disimpan.');}};
  const openIpMenuItem=async item=>{
    if(!['DNS','DHCP Client','Pool'].includes(item))return showSettingInfo(item,'Fitur Pro tidak tersedia. Silakan beli paket Pro untuk menggunakan menu ini.');
    const target=item==='DNS'?'dns':item==='DHCP Client'?'dhcp':'pool';
    setIpSubmenu(target);setIpBusy(true);
    try{
      if(target==='dns'){
        const [settings]=await api('/api/ip/dns');
        setDnsSettings(current=>({...current,servers:settings?.servers||'',dynamicServers:settings?.['dynamic-servers']||'',useDohServer:settings?.['use-doh-server']||'',allowRemoteRequests:['yes','true'].includes(String(settings?.['allow-remote-requests']).toLowerCase())?'yes':'no',maxUdpPacketSize:settings?.['max-udp-packet-size']||current.maxUdpPacketSize,queryServerTimeout:settings?.['query-server-timeout']||current.queryServerTimeout,queryTotalTimeout:settings?.['query-total-timeout']||current.queryTotalTimeout,maxConcurrentQueries:settings?.['max-concurrent-queries']||current.maxConcurrentQueries,maxConcurrentTcpSessions:settings?.['max-concurrent-tcp-sessions']||current.maxConcurrentTcpSessions,cacheSize:settings?.['cache-size']||current.cacheSize,cacheMaxTtl:settings?.['cache-max-ttl']||current.cacheMaxTtl,cacheUsed:settings?.['cache-used']||''}));
      }else if(target==='dhcp'){
        const [clients,interfaces]=await Promise.all([api('/api/ip/dhcp-clients'),api('/api/router/interfaces')]);setDhcpClients(clients);setIpInterfaces(interfaces);
      }else setIpPools(await api('/api/ip/pools'));
    }catch(e){Alert.alert(`Gagal membuka ${item}`,e.message||'Data tidak dapat dibaca dari MikroTik.');}
    finally{setIpBusy(false);}
  };
  const saveDnsSettings=async()=>{
    setIpBusy(true);
    try{await api('/api/ip/dns',{method:'PATCH',body:JSON.stringify({'servers':dnsSettings.servers,'use-doh-server':dnsSettings.useDohServer,'allow-remote-requests':dnsSettings.allowRemoteRequests,'max-udp-packet-size':dnsSettings.maxUdpPacketSize,'query-server-timeout':dnsSettings.queryServerTimeout,'query-total-timeout':dnsSettings.queryTotalTimeout,'max-concurrent-queries':dnsSettings.maxConcurrentQueries,'max-concurrent-tcp-sessions':dnsSettings.maxConcurrentTcpSessions,'cache-size':dnsSettings.cacheSize,'cache-max-ttl':dnsSettings.cacheMaxTtl})});Alert.alert('Tersimpan','Pengaturan DNS MikroTik berhasil diperbarui.');await openIpMenuItem('DNS');}
    catch(e){Alert.alert('Gagal menyimpan DNS',e.message||'RouterOS menolak pengaturan DNS.');}
    finally{setIpBusy(false);}
  };
  const openDhcpClientForm=(item=null)=>{const rawOptions=item?.['dhcp-options'];const dhcpOptions=Array.isArray(rawOptions)?rawOptions:String(rawOptions||'hostname,clientid').split(',').map(value=>value.trim()).filter(Boolean);setDhcpClientForm({id:item?.['.id']||'',enabled:item?.disabled==='true'?'no':'yes',comment:item?.comment||'',interface:item?.interface||ipInterfaces[0]?.name||'',usePeerDns:item?.['use-peer-dns']||'yes',usePeerNtp:item?.['use-peer-ntp']||'yes',addDefaultRoute:item?.['add-default-route']||'yes',dhcpOptions,defaultRouteDistance:item?.['default-route-distance']||'1',script:item?.script||'',status:item?.status||'stopped',address:item?.address||'',gateway:item?.gateway||'',dhcpServer:item?.['dhcp-server']||'',expiresAfter:item?.['expires-after']||'',primaryDns:item?.['primary-dns']||'',secondaryDns:item?.['secondary-dns']||'',primaryNtp:item?.['primary-ntp']||'',secondaryNtp:item?.['secondary-ntp']||'',capsManager:item?.['caps-manager']||''});setDhcpClientTab('dhcp');setIpSubmenu('dhcpForm');};
  const saveDhcpClient=async()=>{if(!dhcpClientForm.interface)return Alert.alert('Interface wajib dipilih','Pilih interface untuk DHCP Client.');setIpBusy(true);try{const {id,status,address,gateway,dhcpServer,expiresAfter,primaryDns,secondaryDns,primaryNtp,secondaryNtp,capsManager,enabled,dhcpOptions,defaultRouteDistance,script,...fields}=dhcpClientForm;const body={interface:fields.interface,comment:fields.comment,'use-peer-dns':fields.usePeerDns,'use-peer-ntp':fields.usePeerNtp,'add-default-route':fields.addDefaultRoute,'dhcp-options':dhcpOptions.filter(Boolean).join(','),'default-route-distance':defaultRouteDistance,script,disabled:enabled==='yes'?'no':'yes'};await api(id?`/api/ip/dhcp-clients/${encodeURIComponent(id)}`:'/api/ip/dhcp-clients',{method:id?'PATCH':'POST',body:JSON.stringify(body)});setDhcpClients(await api('/api/ip/dhcp-clients'));setIpSubmenu('dhcp');Alert.alert('Tersimpan',id?'DHCP Client diperbarui.':'DHCP Client ditambahkan.');}catch(e){Alert.alert('Gagal menyimpan DHCP Client',e.message||'RouterOS menolak pengaturan.');}finally{setIpBusy(false);}};
  const runDhcpAction=async(item,action)=>{try{await api(`/api/ip/dhcp-clients/${encodeURIComponent(item['.id']||item.id)}/${action}`,{method:'POST'});setDhcpClients(await api('/api/ip/dhcp-clients'));}catch(e){Alert.alert(`Gagal ${action==='release'?'melepas':'memperbarui'} lease`,e.message||'Operasi DHCP Client gagal.');}};
  const removeDhcpClient=item=>Alert.alert('Hapus DHCP Client?',`DHCP Client di interface ${item.interface} akan dihapus.`,[{text:'Batal',style:'cancel'},{text:'Hapus',style:'destructive',onPress:async()=>{try{await api(`/api/ip/dhcp-clients/${encodeURIComponent(item['.id'])}`,{method:'DELETE'});setDhcpClients(await api('/api/ip/dhcp-clients'));}catch(e){Alert.alert('Gagal menghapus DHCP Client',e.message||'Operasi gagal.');}}}]);
  const openIpPoolForm=(item=null)=>{setIpPoolForm({id:item?.['.id']||'',comment:item?.comment||'',name:item?.name||'',ranges:item?.ranges||'',nextPool:item?.['next-pool']||'none'});setIpSubmenu('poolForm');};
  const saveIpPool=async()=>{if(!ipPoolForm.name.trim()||!ipPoolForm.ranges.split(',').some(range=>range.trim()))return Alert.alert('Data belum lengkap','Nama pool dan setidaknya satu alamat wajib diisi.');setIpBusy(true);try{const {id,...form}=ipPoolForm;await api(id?`/api/ip/pools/${encodeURIComponent(id)}`:'/api/ip/pools',{method:id?'PATCH':'POST',body:JSON.stringify({'name':form.name,comment:form.comment,ranges:form.ranges.split(',').map(range=>range.trim()).filter(Boolean).join(','),'next-pool':form.nextPool||'none'})});setIpPools(await api('/api/ip/pools'));setIpSubmenu('pool');Alert.alert('Tersimpan',id?'IP Pool diperbarui.':'IP Pool ditambahkan.');}catch(e){Alert.alert('Gagal menyimpan IP Pool',e.message||'RouterOS menolak pengaturan.');}finally{setIpBusy(false);}};
  const removeIpPool=item=>Alert.alert('Hapus IP Pool?',`Pool ${item.name} akan dihapus dari MikroTik.`,[{text:'Batal',style:'cancel'},{text:'Hapus',style:'destructive',onPress:async()=>{try{await api(`/api/ip/pools/${encodeURIComponent(item['.id'])}`,{method:'DELETE'});setIpPools(await api('/api/ip/pools'));}catch(e){Alert.alert('Gagal menghapus IP Pool',e.message||'Pool mungkin masih dipakai router.');}}}]);
  const saveVoucherSettings=async()=>{try{await AsyncStorage.setItem(VOUCHER_SETTINGS_KEY,JSON.stringify(voucherSettings));setSettingsView('menu');Alert.alert('Tersimpan','Pengaturan dan template voucher disimpan di perangkat ini.');}catch(e){Alert.alert('Gagal menyimpan',e.message||'Pengaturan voucher tidak dapat disimpan.');}};
  const pickVoucherLogo=async()=>{try{const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted)return Alert.alert('Izin diperlukan','Izinkan akses foto untuk memilih logo voucher.');const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],base64:true,quality:.75});if(!result.canceled&&result.assets?.[0]?.base64)setVoucherSettings(current=>({...current,logo:`data:${result.assets[0].mimeType||'image/jpeg'};base64,${result.assets[0].base64}`}));}catch(e){Alert.alert('Gagal memilih logo',e.message||'Logo tidak dapat dibuka.');}};
