function formatRate(value){return formatTrafficRate(value);}
function formatUptime(value){
  if(value===null||value===undefined||value==='')return DASH;
  const raw=String(value).trim();
  const parts={w:0,d:0,h:0,m:0,s:0};
  const matches=[...raw.matchAll(/(\d+)([wdhms])/gi)];
  if(matches.length&&matches.map(match=>match[0]).join('')===raw.replace(/\s+/g,'')){
    for(const [,amount,unit] of matches)parts[unit.toLowerCase()]=Number(amount);
    const totalDays=parts.w*7+parts.d;
    const pad=n=>String(n).padStart(2,'0');
    return `${pad(totalDays)}:${pad(parts.h)}:${pad(parts.m)}:${pad(parts.s)}`;
  }
  return raw;
}
function formatSessionUptime(value){
  if(value===null||value===undefined||value==='')return '00:00:00';
  const raw=String(value).trim();
  if(/^\d+:\d{2}:\d{2}$/.test(raw))return raw;
  let seconds=0;
  const matches=[...raw.matchAll(/(\d+)([wdhms])/gi)];
  if(matches.length&&matches.map(match=>match[0]).join('')===raw.replace(/\s+/g,'')){
    const units={w:604800,d:86400,h:3600,m:60,s:1};
    seconds=matches.reduce((total,[,amount,unit])=>total+Number(amount)*units[unit.toLowerCase()],0);
  }else if(/^\d+:\d{2}:\d{2}:\d{2}$/.test(raw)){
    const [days,hours,minutes,secs]=raw.split(':').map(Number);
    seconds=((days*24+hours)*60+minutes)*60+secs;
  }else return raw;
  const pad=value=>String(value).padStart(2,'0');
  return `${pad(Math.floor(seconds/3600))}:${pad(Math.floor(seconds/60)%60)}:${pad(seconds%60)}`;
}

